from pathlib import Path
import re
p=Path('index.html')
s=p.read_text(encoding='utf-8')

# marker
s=s.replace('/* WORKFLOW_ENGINE_V3_UI_2026_09_17 */','/* WORKFLOW_ENGINE_V3_UI_2026_09_17 */\n/* WORKCENTER_UI_CONSOLIDATION_V31_2026_09_17 */')

# Navigation: Work Center becomes the primary operations entry; legacy operation pages stay in DOM but leave main nav.
old_nav='''<details class="nav-group" open><summary>الرئيسية</summary><button class="nav active" data-page="dashboard">لوحة المعلومات</button></details>\n<details class="nav-group" open><summary>البنوك</summary><button class="nav" data-page="banks">السيولة</button></details>\n<details class="nav-group" open><summary>المدفوعات</summary><button class="nav" data-page="payments">الاعتمادات</button><button class="nav" data-page="pending">المعلقة</button><button class="nav" data-page="posted">المرحلة</button></details>\n<details class="nav-group" open><summary>التشغيل</summary><button class="nav" data-page="tasks">المهام</button><button class="nav" data-page="workflow">سير العمل</button><button class="nav" data-page="control">التحكم اليومي</button><button class="nav" data-page="workload">عبء العمل</button><button class="nav" data-page="escalations">التعثر</button></details>'''
new_nav='''<details class="nav-group" open><summary>الرئيسية</summary><button class="nav active" data-page="workcenter">مركز العمل</button><button class="nav" data-page="dashboard">لوحة المعلومات</button></details>\n<details class="nav-group" open><summary>البنوك</summary><button class="nav" data-page="banks">السيولة</button></details>\n<details class="nav-group" open><summary>المدفوعات</summary><button class="nav" data-page="payments">الاعتمادات</button><button class="nav" data-page="pending">المعلقة</button><button class="nav" data-page="posted">المرحلة</button></details>'''
if old_nav not in s: raise SystemExit('nav anchor not found')
s=s.replace(old_nav,new_nav)

# Consolidated Work Center section.
wc='''<section id="workcenter" class="section">\n<div class="row" style="margin-bottom:12px"><div><h3 style="margin:0">مركز العمل</h3><div class="muted">واجهة التشغيل اليومية الموحدة: المهام، المراجعات، الاستثناءات، وخطة اليوم في مكان واحد.</div></div><div class="lang-actions"><button id="wcWorkdayBtn" class="btn" type="button" onclick="toggleWorkday()">بدء يوم العمل</button><button id="wcNotificationsBtn" class="btn" type="button" onclick="openTaskNotifications()">التنبيهات</button><button id="wcDailyPlanBtn" class="btn success" type="button" onclick="openDailyPlan()">إعداد / بدء خطة اليوم</button><button id="wcAddTaskBtn" class="btn primary" type="button" onclick="openTaskModal()">+ إضافة مهمة</button><button class="btn" type="button" onclick="loadWorkCenter()">تحديث</button></div></div>\n<div class="card" style="margin-bottom:12px"><div class="row"><div class="workcenter-tabs"><button class="btn active" data-wctab="active" onclick="setWorkCenterTab('active')">عملي الآن <span id="wcCountActive"></span></button><button class="btn" data-wctab="waiting_on_me" onclick="setWorkCenterTab('waiting_on_me')">بانتظار مني <span id="wcCountWaitingMe"></span></button><button class="btn" data-wctab="waiting_others" onclick="setWorkCenterTab('waiting_others')">بانتظار الآخرين <span id="wcCountWaitingOthers"></span></button><button class="btn" data-wctab="exceptions" onclick="setWorkCenterTab('exceptions')">الاستثناءات <span id="wcCountExceptions"></span></button><button class="btn" data-wctab="completed_today" onclick="setWorkCenterTab('completed_today')">مكتمل اليوم <span id="wcCountCompleted"></span></button></div><div id="wcScopeWrap" class="workcenter-scope"><button id="wcMineBtn" class="btn active" onclick="setWorkCenterScope('mine')">عملي</button><button id="wcTeamBtn" class="btn" onclick="setWorkCenterScope('team')">الفريق</button></div></div></div>\n<div id="workcenterSummary" class="workflow-kpis"></div>\n<div class="card" style="margin-bottom:12px"><div class="filters" style="margin-bottom:0"><select id="wcEmployeeFilter" onchange="loadWorkCenter()"><option value="">كل الموظفين</option></select><select id="wcTypeFilter" onchange="loadWorkCenter()"><option value="">كل أنواع العمل</option><option value="MANUAL_TASK">مهمة يدوية</option><option value="PAYMENT_SUPERVISOR_APPROVAL">اعتماد المشرف</option><option value="PAYMENT_CFO_APPROVAL">اعتماد المدير المالي</option><option value="PAYMENT_BANK_EXECUTION">تنفيذ بنكي</option><option value="PAYMENT_ACCOUNTING_REGISTRATION">تسجيل محاسبي</option><option value="PAYMENT_POSTING_FINALIZATION">ترحيل وإقفال</option></select><select id="wcStatusFilter" onchange="loadWorkCenter()"><option value="">كل الحالات</option><option>Assigned</option><option>Ready</option><option>In Progress</option><option>Paused</option><option>Blocked</option><option>Extension Requested</option><option>Pending Review</option><option>Returned for Rework</option><option>Completed</option></select><select id="wcPriorityFilter" onchange="loadWorkCenter()"><option value="">كل الأولويات</option><option value="حرج">حرج</option><option value="عالي">عالي</option><option value="عادي">عادي</option><option value="منخفض">منخفض</option></select><button class="btn" onclick="clearWorkCenterFilters()">مسح الفلاتر</button></div></div>\n<div class="table-wrap"><table id="workcenterTable"><thead><tr><th>عنصر العمل</th><th>النوع</th><th>المسؤول</th><th>المراجع</th><th>المرحلة</th><th>الحالة</th><th>الأولوية</th><th>الموعد</th><th>الإجراء المطلوب</th></tr></thead><tbody id="workcenterBody"></tbody></table></div>\n</section>'''
pattern=r'<section id="workflow" class="section">.*?</section>\n<section id="control"'
if not re.search(pattern,s,re.S): raise SystemExit('workflow section anchor not found')
s=re.sub(pattern,wc+'\n<section id="control"',s,count=1,flags=re.S)

# CSS
css='''\n.workcenter-tabs,.workcenter-scope{display:flex;gap:7px;flex-wrap:wrap}.workcenter-tabs .btn.active,.workcenter-scope .btn.active{background:var(--nav);color:#fff;border-color:var(--nav)}\n.workcenter-action-primary{background:var(--nav);color:#fff;border-color:var(--nav)}.workcenter-row-overdue{background:#fff8f8}.workcenter-title{min-width:240px;white-space:normal}.workcenter-actions{display:flex;gap:5px;flex-wrap:wrap;min-width:210px}.workcenter-action-note{font-size:11px;color:var(--muted);margin-top:4px}.workcenter-summary-card b{font-size:20px;display:block;margin-top:3px}\n@media(max-width:700px){.workcenter-tabs,.workcenter-scope{width:100%}.workcenter-tabs .btn{flex:1 1 45%}}\n'''
s=s.replace('</style>',css+'</style>',1)

# State variables
s=s.replace('let workflowQueue=[],workflowCompletedToday=[],workflowPerformance=[],workflowScope="ACTIVE";','let workflowQueue=[],workflowCompletedToday=[],workflowPerformance=[],workflowScope="ACTIVE";let workcenterItems=[],workcenterSummary={},workcenterTab=localStorage.getItem("sanam_wc_tab")||"active",workcenterScope=localStorage.getItem("sanam_wc_scope")||"mine";')

# Page access: preserve legacy permissions, add workcenter everywhere finance users already had workflow.
s=re.sub(r'const PAGE_ACCESS=\{CFO:\[(.*?)\],Supervisor:\[(.*?)\],BankAccountant:\[(.*?)\],GLAccountant:\[(.*?)\],ARAccountant:\[(.*?)\],APAccountant:\[(.*?)\]\};',lambda m:'const PAGE_ACCESS={CFO:['+(','.join(['"workcenter"']+[x for x in m.group(1).split(',') if x!='"workcenter"']))+'],Supervisor:['+(','.join(['"workcenter"']+[x for x in m.group(2).split(',') if x!='"workcenter"']))+'],BankAccountant:['+(','.join(['"workcenter"']+[x for x in m.group(3).split(',') if x!='"workcenter"']))+'],GLAccountant:['+(','.join(['"workcenter"']+[x for x in m.group(4).split(',') if x!='"workcenter"']))+'],ARAccountant:['+(','.join(['"workcenter"']+[x for x in m.group(5).split(',') if x!='"workcenter"']))+'],APAccountant:['+(','.join(['"workcenter"']+[x for x in m.group(6).split(',') if x!='"workcenter"']))+']};',s,count=1)

# Translation additions
trans='''Object.assign(I18N_AR_EN,{"مركز العمل":"Work Center","واجهة التشغيل اليومية الموحدة: المهام، المراجعات، الاستثناءات، وخطة اليوم في مكان واحد.":"Unified daily operations workspace for tasks, reviews, exceptions, and the daily plan.","عملي الآن":"My Active Work","بانتظار مني":"Waiting on Me","بانتظار الآخرين":"Waiting on Others","إعداد / بدء خطة اليوم":"Prepare / Start Daily Plan","عملي":"My Work","الفريق":"Team","كل الموظفين":"All Employees","كل أنواع العمل":"All Work Types","كل الحالات":"All Statuses","كل الأولويات":"All Priorities","مسح الفلاتر":"Clear Filters","الإجراء المطلوب":"Required Action","Assigned":"Assigned","Paused":"Paused","Extension Requested":"Extension Requested","Returned for Rework":"Returned for Rework","ACKNOWLEDGE":"Acknowledge","START":"Start","PAUSE":"Pause","RESUME":"Resume","COMMENT":"Comment","PROGRESS_UPDATE":"Progress Update","REQUEST_CLARIFICATION":"Request Clarification","REPORT_BLOCKER":"Report Blocker","RESOLVE_BLOCKER":"Resolve Blocker","REQUEST_EXTENSION":"Request Extension","COMPLETE":"Complete","SUBMIT_FOR_REVIEW":"Submit for Review","APPROVE_EXTENSION":"Approve Extension","REJECT_EXTENSION":"Reject Extension","REQUEST_EXTENSION_INFO":"Request More Information","APPROVE_COMPLETION":"Approve Completion","RETURN_REWORK":"Return for Rework","REASSIGN":"Reassign","CHANGE_DUE":"Change Deadline","CHANGE_PRIORITY":"Change Priority","CHANGE_REVIEWER":"Change Reviewer","REQUEST_JUSTIFICATION":"Request Justification","APPROVE_PAYMENT_SUPERVISOR":"Approve Payment","APPROVE_PAYMENT_CFO":"CFO Approve Payment","EXECUTE_PAYMENT":"Execute Payment","REGISTER_ACCOUNTING":"Register Accounting","FINALIZE_POSTING":"Post / Finalize"});\n'''
s=s.replace('function displayText(v){return tr(v)}',trans+'function displayText(v){return tr(v)}',1)

# Permissions admin: Work Center replaces legacy Workflow entry in visible matrix.
s=s.replace("['page.workflow','سير العمل']","['page.workcenter','مركز العمل']")

# Work Center functions inserted before legacy workflow rendering.
anchor='function workflowTypeLabel(t)'
if anchor not in s: raise SystemExit('workflow function anchor not found')
js=r'''
function workCenterActionLabel(a){return displayText(a||'')}
function workCenterItemById(id){return workcenterItems.find(x=>x.work_item_id===id)}
function workCenterFilters(){const f={};const emp=document.getElementById('wcEmployeeFilter')?.value,type=document.getElementById('wcTypeFilter')?.value,status=document.getElementById('wcStatusFilter')?.value,priority=document.getElementById('wcPriorityFilter')?.value;if(emp)f.employee_id=emp;if(type)f.item_type=type;if(status)f.status=status;if(priority)f.priority=priority;return f}
function populateWorkCenterEmployeeFilter(){const el=document.getElementById('wcEmployeeFilter');if(!el)return;const old=el.value;el.innerHTML=`<option value="">${displayText('كل الموظفين')}</option>`+(profiles||[]).filter(x=>['Supervisor','BankAccountant','GLAccountant','ARAccountant','APAccountant'].includes(x.role)).map(x=>`<option value="${esc(x.id)}">${esc(x.full_name)}</option>`).join('');if([...el.options].some(o=>o.value===old))el.value=old}
function clearWorkCenterFilters(){['wcEmployeeFilter','wcTypeFilter','wcStatusFilter','wcPriorityFilter'].forEach(id=>{const e=document.getElementById(id);if(e)e.value=''});loadWorkCenter()}
function setWorkCenterTab(tab){workcenterTab=tab;localStorage.setItem('sanam_wc_tab',tab);document.querySelectorAll('[data-wctab]').forEach(b=>b.classList.toggle('active',b.dataset.wctab===tab));loadWorkCenter()}
function setWorkCenterScope(scope){if(scope==='team'&&!['CFO','Supervisor'].includes(profile?.role))scope='mine';workcenterScope=scope;localStorage.setItem('sanam_wc_scope',scope);document.getElementById('wcMineBtn')?.classList.toggle('active',scope==='mine');document.getElementById('wcTeamBtn')?.classList.toggle('active',scope==='team');loadWorkCenter()}
async function loadWorkCenter(){if(!canPage('workcenter'))return;if(workcenterScope==='team'&&!['CFO','Supervisor'].includes(profile?.role))workcenterScope='mine';populateWorkCenterEmployeeFilter();document.querySelectorAll('[data-wctab]').forEach(b=>b.classList.toggle('active',b.dataset.wctab===workcenterTab));document.getElementById('wcMineBtn')?.classList.toggle('active',workcenterScope==='mine');document.getElementById('wcTeamBtn')?.classList.toggle('active',workcenterScope==='team');document.getElementById('wcScopeWrap')?.classList.toggle('hidden',!['CFO','Supervisor'].includes(profile?.role));const [items,sum]=await Promise.all([sb.rpc('get_workcenter_items',{p_tab:workcenterTab,p_scope:workcenterScope,p_filters:workCenterFilters()}),sb.rpc('get_workcenter_summary',{p_scope:workcenterScope})]);if(items.error){console.error(items.error);workcenterItems=[]}else workcenterItems=items.data||[];workcenterSummary=sum.error?{}:(sum.data||{});renderWorkCenter()}
function renderWorkCenter(){const body=document.getElementById('workcenterBody'),summary=document.getElementById('workcenterSummary');if(!body||!summary)return;const c=workcenterSummary||{};document.getElementById('wcCountActive').textContent=c.active?`(${latinDigits(c.active)})`:'';document.getElementById('wcCountWaitingMe').textContent=c.waiting_on_me?`(${latinDigits(c.waiting_on_me)})`:'';document.getElementById('wcCountWaitingOthers').textContent=c.waiting_others?`(${latinDigits(c.waiting_others)})`:'';document.getElementById('wcCountExceptions').textContent=c.exceptions?`(${latinDigits(c.exceptions)})`:'';document.getElementById('wcCountCompleted').textContent=c.completed_today?`(${latinDigits(c.completed_today)})`:'';summary.innerHTML=`<div class="card workcenter-summary-card"><span class="muted">${displayText('عملي الآن')}</span><b>${latinDigits(c.active||0)}</b></div><div class="card workcenter-summary-card"><span class="muted">${displayText('بانتظار مني')}</span><b>${latinDigits(c.waiting_on_me||0)}</b></div><div class="card workcenter-summary-card"><span class="muted">${displayText('بانتظار الآخرين')}</span><b>${latinDigits(c.waiting_others||0)}</b></div><div class="card workcenter-summary-card"><span class="muted">${displayText('الاستثناءات')}</span><b>${latinDigits(c.exceptions||0)}</b></div><div class="card workcenter-summary-card"><span class="muted">${displayText('مكتمل اليوم')}</span><b>${latinDigits(c.completed_today||0)}</b></div>`;body.innerHTML=(workcenterItems||[]).map(w=>{const acts=Array.isArray(w.available_actions)?w.available_actions:[];const actionHtml=acts.slice(0,5).map(a=>`<button class="btn ${['START','COMPLETE','APPROVE_COMPLETION','EXECUTE_PAYMENT','REGISTER_ACCOUNTING','FINALIZE_POSTING'].includes(a.action)?'workcenter-action-primary':''}" onclick="openWorkCenterAction('${esc(w.work_item_id)}','${esc(a.action)}')">${esc(workCenterActionLabel(a.action))}</button>`).join('');return `<tr class="${w.is_overdue?'workcenter-row-overdue':''}"><td class="workcenter-title"><b>${esc(w.title)}</b><div class="workflow-source">${esc(workflowSourceLabel(w.source_type))} · ${esc(w.source_id||'')}</div></td><td>${esc(displayText(workflowTypeLabel(w.item_type)))}</td><td>${esc(w.assignee_name||'—')}</td><td>${esc(w.reviewer_name||'—')}</td><td>${esc(displayText(w.current_step_key||'—'))}</td><td>${workflowStatusBadge(w.status)}</td><td>${esc(displayText(w.priority||'—'))}</td><td>${workflowDueHtml(w.due_at,w.status)}</td><td><div class="workcenter-actions">${actionHtml||`<span class="muted">${currentLang==='en'?'No action required':'لا يوجد إجراء مطلوب'}</span>`}<button class="btn" onclick="openWorkflowTimeline('${esc(w.source_type)}','${esc(w.source_id)}','${esc(w.title)}')">${displayText('عرض المسار')}</button></div></td></tr>`}).join('')||`<tr><td colspan="9"><div class="workflow-empty">${displayText('لا توجد عناصر عمل في هذا العرض.')}</div></td></tr>`;applyLanguage(document.getElementById('workcenter'))}
function wcPeopleOptions(selected=''){return (profiles||[]).filter(x=>x.active!==false&&['Supervisor','BankAccountant','GLAccountant','ARAccountant','APAccountant'].includes(x.role)).map(x=>`<option value="${esc(x.id)}" ${x.id===selected?'selected':''}>${esc(x.full_name)} — ${esc(displayText(ROLE_LABEL[x.role]||x.role))}</option>`).join('')}
function openWorkCenterAction(id,action){const w=workCenterItemById(id);if(!w)return;const simple=['ACKNOWLEDGE','START','PAUSE','RESUME','RESOLVE_BLOCKER','APPROVE_EXTENSION','APPROVE_COMPLETION','APPROVE_PAYMENT_SUPERVISOR','APPROVE_PAYMENT_CFO','EXECUTE_PAYMENT','REGISTER_ACCOUNTING','FINALIZE_POSTING'];if(simple.includes(action)){if(confirm(`${workCenterActionLabel(action)} — ${w.title}?`))submitWorkCenterAction(id,action,{});return}let fields='';if(['COMMENT','PROGRESS_UPDATE'].includes(action))fields=`<div><label>${displayText('ملاحظات')}</label><textarea id="wcActionText"></textarea></div>`;else if(['REQUEST_CLARIFICATION','REPORT_BLOCKER','REJECT_EXTENSION','REQUEST_EXTENSION_INFO','RETURN_REWORK','REQUEST_JUSTIFICATION'].includes(action))fields=`<div><label>${displayText('السبب')}</label><textarea id="wcActionReason"></textarea></div>`;else if(action==='REQUEST_EXTENSION')fields=`<div class="modal-grid">${input('wcDueDate',displayText('تاريخ التسليم'),'','date')}${input('wcDueTime',displayText('وقت التسليم'),'','time')}</div><div style="margin-top:10px"><label>${displayText('مبرر التمديد')}</label><textarea id="wcActionReason"></textarea></div>`;else if(action==='REASSIGN')fields=`<div><label>${displayText('المسؤول')}</label><select id="wcNewOwner">${wcPeopleOptions(w.assignee_id)}</select></div><div style="margin-top:10px"><label>${displayText('سبب التغيير')}</label><textarea id="wcActionReason"></textarea></div>`;else if(action==='CHANGE_DUE')fields=`<div class="modal-grid">${input('wcDueDate',displayText('تاريخ التسليم'),'','date')}${input('wcDueTime',displayText('وقت التسليم'),'','time')}</div><div style="margin-top:10px"><label>${displayText('سبب التغيير')}</label><textarea id="wcActionReason"></textarea></div>`;else if(action==='CHANGE_PRIORITY')fields=`<div><label>${displayText('الأولوية')}</label><select id="wcPriority"><option value="حرج">${displayText('حرج')}</option><option value="عالي">${displayText('عالي')}</option><option value="عادي">${displayText('عادي')}</option><option value="منخفض">${displayText('منخفض')}</option></select></div>`;else if(action==='CHANGE_REVIEWER')fields=`<div><label>${displayText('المراجع')}</label><select id="wcReviewer">${wcPeopleOptions(w.reviewer_id)}</select></div><div style="margin-top:10px"><label>${displayText('سبب التغيير')}</label><textarea id="wcActionReason"></textarea></div>`;else fields=`<div><label>${displayText('ملاحظات')}</label><textarea id="wcActionReason"></textarea></div>`;showModal(`${workCenterActionLabel(action)} — ${w.title}`,`${fields}<div style="margin-top:14px;text-align:end"><button class="btn primary" onclick="submitWorkCenterActionFromModal('${esc(id)}','${esc(action)}')">${displayText('حفظ')}</button></div>`)}
function submitWorkCenterActionFromModal(id,action){const payload={};const reason=document.getElementById('wcActionReason')?.value?.trim();const text=document.getElementById('wcActionText')?.value?.trim();if(reason)payload.reason=reason;if(action==='COMMENT')payload.body=text||'';if(action==='PROGRESS_UPDATE')payload.note=text||'';if(action==='REQUEST_EXTENSION'){payload.requested_due_date=val('wcDueDate');payload.requested_due_time=val('wcDueTime');payload.justification=reason||''}if(action==='REASSIGN')payload.new_owner_id=val('wcNewOwner');if(action==='CHANGE_DUE'){payload.due_date=val('wcDueDate');payload.due_time=val('wcDueTime')}if(action==='CHANGE_PRIORITY')payload.priority=val('wcPriority');if(action==='CHANGE_REVIEWER')payload.reviewer_id=val('wcReviewer');submitWorkCenterAction(id,action,payload)}
async function submitWorkCenterAction(id,action,payload){const {data,error}=await sb.rpc('try_perform_work_item_action',{p_work_item_id:id,p_action:action,p_payload:payload||{}});if(error){alert(error.message);return}if(!data?.ok){alert(data?.error||'تعذر تنفيذ الإجراء');return}closeModal();await reloadAll();await loadWorkCenter()}
'''
s=s.replace(anchor,js+'\n'+anchor,1)

# Permission list visible in admin.
s=s.replace("['page.tasks','المهام'],['page.workcenter','مركز العمل']","['page.workcenter','مركز العمل'],['page.tasks','المهام']") if "['page.workcenter','مركز العمل']" in s else s

# App entry: Work Center is primary landing page.
old_enter='async function enterApp(){const {data:u}=await sb.from("profiles").select("*").eq("id",session.user.id).maybeSingle();if(!u){showAuth();loginMsg.textContent=displayText("الحساب غير مصرح أو لم يكتمل إنشاؤه.");return}profile=u;await loadMyPermissions();authScreen.classList.add("hidden");app.classList.remove("hidden");userRole.textContent=`${profile.full_name} — ${displayText(ROLE_LABEL[profile.role]||profile.role)}`;applyAccess();await reloadAll();if(!canPage(\'dashboard\')){const first=[...document.querySelectorAll(\'.nav\')].find(b=>!b.classList.contains(\'hidden\'));if(first)openPage(first.dataset.page,first.textContent)}applyLanguage()}'
# use direct more tolerant replacement
s=re.sub(r'async function enterApp\(\)\{.*?applyLanguage\(\)\}', '''async function enterApp(){const {data:u}=await sb.from("profiles").select("*").eq("id",session.user.id).maybeSingle();if(!u){showAuth();loginMsg.textContent=displayText("الحساب غير مصرح أو لم يكتمل إنشاؤه.");return}profile=u;await loadMyPermissions();authScreen.classList.add("hidden");app.classList.remove("hidden");userRole.textContent=`${profile.full_name} — ${displayText(ROLE_LABEL[profile.role]||profile.role)}`;applyAccess();await reloadAll();if(canPage('workcenter'))openPage('workcenter',displayText('مركز العمل'));else if(canPage('dashboard'))openPage('dashboard',displayText('لوحة المعلومات'));else{const first=[...document.querySelectorAll('.nav')].find(b=>!b.classList.contains('hidden'));if(first)openPage(first.dataset.page,first.textContent)}applyLanguage()}''', s, count=1, flags=re.S)

# Apply access includes consolidated header actions.
s=s.replace('dailyPlanBtn.classList.toggle("hidden",!["Supervisor","CFO"].includes(profile.role));','dailyPlanBtn.classList.toggle("hidden",!["Supervisor","CFO"].includes(profile.role));document.getElementById("wcDailyPlanBtn")?.classList.toggle("hidden",!["Supervisor","CFO"].includes(profile.role));document.getElementById("wcAddTaskBtn")?.classList.toggle("hidden",!["Supervisor","CFO"].includes(profile.role));')

# openPage Work Center loader.
s=s.replace("if(id==='workflow')loadWorkflowCenter(workflowScope)","if(id==='workflow')loadWorkflowCenter(workflowScope);if(id==='workcenter')loadWorkCenter()")

# visible permission matrix entry
s=s.replace("['page.workflow','سير العمل']","['page.workcenter','مركز العمل']")

p.write_text(s,encoding='utf-8')
print('patched',len(s))
